@Transactional
public ApprovalResult approve(Long orderId, User approver) {
    if (!approver.hasRole("MANAGER")) throw new ForbiddenException();
    orderRepository.markApproved(orderId);
    auditRepository.record(orderId, approver.getId(), "APPROVED"); // même transaction
    return ApprovalResult.OK;
}
